#include <stdint.h>
#include<UART.h>

int main(void)
{
    uint8_t data;

    UART_GPIO_Init();
    UART_Init();

    while(1)
    {
        data = UART_Receive_Data();

        if(data == 'A')
        {
            UART_Transmit_String("A\r\n");
        }
    }
}
